def apply_rule_neighbor_threshold(grid, min_neighbors=3):
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            # Count orthogonal neighbors with same value
            same_count = sum(1 for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]
                           if 0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc] == val)

            print(f"({r},{c}): {val}, orthogonal_same={same_count}")

            # If not enough neighbors, flip to something else (maybe the other color?)
            if same_count < min_neighbors:
                # Find what other color is around
                diff_vals = set()
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    if 0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc] != val:
                        diff_vals.add(grid[r+dr][c+dc])
                if len(diff_vals) > 0:
                    new_val = list(diff_vals)[0]  # Take first different value
                    result[r][c] = new_val
    return result

