from collections import deque

def find_largest_components_and_clean(grid):
    """Keep only the largest connected component for each color"""
    h, w = len(grid), len(grid[0])

    colors_present = set()
    for r in range(h):
        for c in range(w):
            colors_present.add(grid[r][c])

    results = {}

    for color in colors_present:
        # Find all components of this color
        visited = set()
        components = []

        for r in range(h):
            for c in range(w):
                if grid[r][c] == color and (r,c) not in visited:
                    comp_cells = [(r,c)]
                    queue = deque([(r,c)])
                    while queue:
                        cr, cc = queue.popleft()
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr,nc) not in visited:
                                queue.append((nr,nc))
                                comp_cells.append((nr,nc))
                                visited.add((nr,nc))
                    components.append(comp_cells)

        # Keep only the largest component
        if components:
            largest = max(components, key=len)
            results[color] = largest

    return results

