def apply_rule_min_neighbors(grid, min_same=2):
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            same_count = sum(1 for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] 
                           if 0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc] == val)

            if same_count < min_same:
                # Change to majority of neighboring cells
                neighbors = []
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<h and 0<=nc<w:
                        neighbors.append(grid[nr][nc])

                if neighbors:
                    counts = {}
                    for v in neighbors:
                        counts[v] = counts.get(v, 0) + 1
                    result[r][c] = max(counts, key=lambda x: counts[x])
                else:
                    # No neighbors, keep original or use background assumption
                    result[r][c] = grid[r][c]  # Keep

    return result

