def neighbor_majority_rule(grid):
    """If cell has < X% same-color orthogonal neighbors, change to majority neighbor color"""
    h, w = len(grid), len(grid[0])

    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        for c in range(w):
            val = grid[r][c]

            # Count orthogonal neighbors
            orth_neighbors = []
            same_count = 0
            diff_vals = set()

            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w:
                    nval = grid[nr][nc]
                    orth_neighbors.append(nval)
                    if nval == val:
                        same_count += 1
                    else:
                        diff_vals.add(nval)

            total = len(orth_neighbors)
            if total > 0:
                pct_same = same_count / total

                print(f"({r},{c}): {val}, {same_count}/{total}={pct_same:.0%} same")

                # If less than 60% are same, change to majority diff value
                if pct_same < 0.6 and diff_vals:
                    # Majority among different values
                    counts = {}
                    for v in orth_neighbors:
                        if v != val:
                            counts[v] = counts.get(v, 0) + 1

                    new_val = max(counts.keys(), key=lambda x: counts[x])
                    result[r][c] = new_val

    return result

